<?php

declare(strict_types=1);

namespace WPEssential\Tests\Unit\Modules\FormsWorkflows;

use InvalidArgumentException; use PHPUnit\Framework\TestCase; use WPEssential\Contracts\CapabilityCheckerInterface; use WPEssential\Kernel\ServiceRegistry; use WPEssential\Modules\FormsWorkflows\FormWorkflowDefinition; use WPEssential\Modules\FormsWorkflows\FormsWorkflowsModule; use WPEssential\Modules\FormsWorkflows\FormsWorkflowsReadAbilityHandler; use WPEssential\Modules\FormsWorkflows\FormsWorkflowsReadService; use WPEssential\Platform\Abilities\AbilityRegistry; use WPEssential\Platform\Auth\ExecutionChannel; use WPEssential\Platform\Auth\ExecutionContext; use WPEssential\Platform\Auth\PolicyEngine; use WPEssential\Platform\Auth\Principal; use WPEssential\Platform\Definitions\InMemoryDefinitionRepository; use WPEssential\Platform\WordPress\Abilities\WordPressAbilityBridge; use WPEssential\Platform\WordPress\Abilities\WordPressAbilityEnvironmentInterface; use WPEssential\Platform\WordPress\Abilities\WordPressExecutionContextFactory;

final class FormsWorkflowsModuleTest extends TestCase
{
    public function testModuleRegistersBoundedReadOnlyAbilitiesAndBridgeExposure():void{$definitions=new InMemoryDefinitionRepository();$services=new ServiceRegistry();$abilities=new AbilityRegistry(new PolicyEngine(new class implements CapabilityCheckerInterface{public function can(ExecutionContext $context,string $capability):bool{return true;}}));$environment=new class implements WordPressAbilityEnvironmentInterface{public function abilitiesApiAvailable():bool{return true;}public function doingAction(string $hook):bool{return $hook==='wp_abilities_api_init';}public function currentUserId():?int{return 1;}public function currentSiteId():int{return 1;}public function currentNetworkId():?int{return null;}public function currentUserCan(string $capability):bool{return true;}public function isRestRequest():bool{return false;}public function isCli():bool{return false;}public function registerCategory(string $slug,array $args):bool{return true;}public function registerAbility(string $name,array $args):bool{return true;}};$bridge=new WordPressAbilityBridge($abilities,$environment,new WordPressExecutionContextFactory($environment));$services->set('platform.definitions',$definitions);$services->set('platform.abilities',$abilities);$services->set('platform.abilities.wordpress',$bridge);(new FormsWorkflowsModule())->register($services);self::assertInstanceOf(FormsWorkflowsReadService::class,$services->get(FormsWorkflowsModule::SERVICE_READ));foreach([FormsWorkflowsModule::ABILITY_GET,FormsWorkflowsModule::ABILITY_CATALOG]as$name){$d=$abilities->descriptor($name);self::assertNotNull($d);self::assertFalse($d->mutates);self::assertSame(FormWorkflowDefinition::OWNER_SURFACE_ID,$d->ownerSurfaceId);self::assertSame(FormsWorkflowsModule::CAPABILITY,$d->capability);self::assertTrue($d->allows(ExecutionChannel::Internal));self::assertTrue($d->allows(ExecutionChannel::Ui));self::assertTrue($d->allows(ExecutionChannel::Rest));}self::assertCount(2,$bridge->registerAbilities());}
    public function testHandlerDelegatesReadOnlyGetAndCatalog():void{$service=new FormsWorkflowsReadService(new InMemoryDefinitionRepository());$context=new ExecutionContext(new Principal(1),1);self::assertNull((new FormsWorkflowsReadAbilityHandler($service,FormsWorkflowsReadAbilityHandler::GET))->handle(['id'=>'missing'],$context));self::assertSame([],(new FormsWorkflowsReadAbilityHandler($service,FormsWorkflowsReadAbilityHandler::CATALOG))->handle([],$context));}
    public function testHandlerRejectsMutationShapedCatalogInput():void{$this->expectException(InvalidArgumentException::class);$service=new FormsWorkflowsReadService(new InMemoryDefinitionRepository());(new FormsWorkflowsReadAbilityHandler($service,FormsWorkflowsReadAbilityHandler::CATALOG))->handle(['save'=>true],new ExecutionContext(new Principal(1),1));}
}
